from public.price_snapshots ps
where ps.reference_variant_id = (select rv.id from public.reference_variants rv join public.reference_models rm on rm.id = rv.reference_model_id join public.collections c on c.id = rm.collection_id join public.brands b on b.id = c.brand_id where b.slug = 'tudor' and rv.variant_key = 'tudor-m79000n-0001')
  and ps.kind = 'retail' and ps.condition = 'new'
  and ps.currency = 'PLN'
  and ps.observed_at = '2026-08-29T08:47:00Z'::timestamptz
